INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e8800001-8888-4888-8888-888888888888', 'TUT-KOMPUTER21-001', 'baaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', $$Task Manager: Atasi Komputer Lemot$$, 'task-manager-atasi-komputer-lemot', $$Panduan memakai Task Manager untuk menemukan penyebab komputer lemot dan mengatasinya dengan aman.$$, 'id', 6, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Komputer Tiba-tiba Lemot$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Komputer yang tadinya cepat bisa tiba-tiba lemot: membuka aplikasi lama, kursor macet, atau kipas berputar kencang. Sebelum panik atau membawa ke tukang servis, langkah pertama yang paling ampuh adalah membuka Task Manager untuk melihat apa yang sebenarnya membebani komputer.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Apa Itu Task Manager$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Task Manager adalah alat bawaan Windows yang menampilkan semua program dan proses yang sedang berjalan, beserta penggunaan CPU, memori (RAM), disk, dan jaringan. Cara membukanya: tekan Ctrl+Shift+Esc, atau klik kanan taskbar lalu pilih Task Manager.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Dibutuhkan$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Komputer Windows (7, 10, atau 11)$$,$$Akses administrator (untuk menghentikan proses sistem tertentu)$$,$$Catatan kecil untuk mencatat nama proses yang mencurigakan$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Menemukan dan Mengatasi Penyebab Lemot$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Buka Task Manager dengan Ctrl+Shift+Esc, klik tab Processes.$$,$$Klik kolom CPU atau Memory untuk mengurutkan dari yang paling besar.$$,$$Perhatikan aplikasi dengan angka CPU/Memory tinggi yang tidak sedang kamu pakai.$$,$$Klik kanan aplikasi tersebut lalu pilih End Task untuk menghentikannya.$$,$$Buka tab Startup, nonaktifkan (Disable) aplikasi yang tidak perlu berjalan saat komputer dinyalakan.$$,$$Restart komputer dan rasakan perbedaannya.$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko yang Perlu Diwaspadai$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Jangan asal menghentikan proses: proses bernama svchost.exe, System, atau explorer.exe adalah bagian penting Windows. Menghentikannya bisa membuat layar hitam atau komputer restart sendiri. Jika ragu, cukup hentikan aplikasi yang jelas kamu kenal, seperti browser atau game.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Setelah langkah di atas, penggunaan CPU saat idle sebaiknya di bawah 20 persen. Jika komputer tetap lemot, kemungkinan penyebabnya adalah RAM penuh, hard disk hampir penuh, atau malware. Lakukan pemindaian antivirus dan pertimbangkan upgrade ke SSD untuk peningkatan kecepatan yang paling terasa.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e8800002-8888-4888-8888-888888888888', 'TUT-KESEHATAN37-001', 'b5555555-5555-5555-5555-555555555555', $$Sakit Pinggang: Penyebab Umum$$, 'sakit-pinggang-penyebab-umum', $$Mengenali penyebab umum sakit pinggang, langkah mandiri yang aman, dan tanda kapan harus ke dokter.$$, 'id', 6, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Pinggang Sakit dan Mengganggu Aktivitas$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Sakit pinggang adalah keluhan yang sangat umum: nyeri tumpul di punggung bawah setelah duduk lama, mengangkat barang berat, atau bangun tidur. Kabar baiknya, sebagian besar sakit pinggang bersifat ringan dan membaik dalam beberapa hari dengan penanganan mandiri yang tepat.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Penyebab Umum Sakit Pinggang$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Penyebab tersering adalah ketegangan otot (muscle strain) akibat postur duduk yang buruk, mengangkat beban dengan teknik salah, atau kurang bergerak. Faktor lain: duduk terlalu lama, kasur yang tidak mendukung, dan kelebihan berat badan yang membebani tulang belakang.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Persiapan dan Alat Bantu$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Kompres hangat atau handuk hangat$$,$$Bantal kecil untuk menopang punggung saat duduk$$,$$Obat pereda nyeri yang dijual bebas (bila perlu, ikuti aturan pakai)$$,$$Alas tidur yang cukup menopang tubuh$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Penanganan Mandiri yang Aman$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Istirahat secukupnya, tetapi jangan berbaring total lebih dari 1-2 hari.$$,$$Tempelkan kompres hangat 15-20 menit pada area yang nyeri.$$,$$Perbaiki postur duduk: punggung tegak, kaki menapak lantai.$$,$$Lakukan peregangan ringan, seperti menarik lutut ke dada secara perlahan.$$,$$Hindari mengangkat barang berat sampai nyeri mereda.$$,$$Tidur miring dengan bantal di antara lutut untuk mengurangi tekanan pinggang.$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Hindari memijat terlalu keras pada area yang nyeri tajam, mengonsumsi obat nyeri melebihi dosis, atau memaksakan olahraga berat. Terapi alternatif yang tidak jelas keamanannya sebaiknya dikonsultasikan dulu ke tenaga kesehatan.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kapan ke Dokter dan Pencegahan$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Segera konsultasikan ke dokter jika nyeri sangat hebat, menjalar ke kaki, disertai kesemutan atau mati rasa, gangguan buang air, demam, atau tidak membaik setelah 2 minggu. Untuk pencegahan: rutin berolahraga ringan, jaga berat badan ideal, angkat beban dengan lutut ditekuk, dan bangun dari duduk setiap 30-60 menit. Catatan: artikel ini bersifat informasi umum dan bukan pengganti nasihat medis.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e8800003-8888-4888-8888-888888888888', 'EXP-ANTROPOLOGI20-001', 'c8888888-8888-8888-8888-888888888888', $$Suku Jawa: Filosofi Hidup$$, 'suku-jawa-filosofi-hidup', $$Menjelajahi filosofi hidup suku Jawa: dari alon-alon asal kelakon hingga konsep harmoni semesta.$$, 'id', 5, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Siapa Suku Jawa$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Suku Jawa adalah kelompok etnis terbesar di Indonesia, berpusat di Jawa Tengah, Jawa Timur, dan Daerah Istimewa Yogyakarta. Dengan populasi ratusan juta jiwa, budaya Jawa memberi warna kuat pada bahasa, seni, dan cara berpikir masyarakat Indonesia.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Alon-alon Asal Kelakon$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Pepatah paling terkenal: alon-alon asal kelakon, artinya pelan-pelan asal terlaksana. Filosofi ini mengajarkan kesabaran, ketekunan, dan tidak terburu-buru dalam mengejar tujuan. Dalam dunia modern yang serba cepat, nilai ini justru menjadi penyeimbang yang berharga.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Nrimo dan Kesederhanaan$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Nrimo berarti menerima keadaan dengan lapang dada, bukan pasrah tanpa usaha. Orang Jawa diajarkan berusaha maksimal lalu menerima hasilnya dengan tenang. Sikap ini melahirkan ketahanan mental menghadapi kegagalan.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Harmoni: Memayu Hayuning Bawana$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Memayu hayuning bawana berarti memperindah keindahan dunia. Manusia dipandang sebagai bagian dari semesta yang wajib menjaga keseimbangan dengan alam, sesama, dan Sang Pencipta. Konsep ini mirip dengan gagasan keberlanjutan modern.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Tata Krama dan Unggah-ungguh$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Bahasa Jawa memiliki tingkatan (ngoko, madya, krama) yang mencerminkan penghormatan pada lawan bicara. Unggah-ungguh, tata cara bersikap, mengajarkan empati: menempatkan diri sebelum berbicara atau bertindak.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e8800004-8888-4888-8888-888888888888', 'EXP-KIMIA32-001', 'c4444444-4444-4444-4444-444444444444', $$Klorin: Unsur Disinfektan$$, 'klorin-unsur-disinfektan', $$Mengenal klorin: sifat kimia, peran sebagai disinfektan air, dan cara aman menggunakannya.$$, 'id', 5, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Klorin$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Klorin adalah unsur kimia dengan simbol Cl dan nomor atom 17. Pada suhu ruang ia berupa gas berwarna kuning kehijauan dengan bau menyengat. Klorin termasuk golongan halogen, kelompok unsur yang sangat reaktif.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Sifat Kimia Klorin$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Klorin mudah bereaksi dengan banyak unsur, terutama logam dan hidrogen, membentuk senyawa seperti natrium klorida (garam dapur) dan hidrogen klorida. Sifat oksidatornya yang kuat inilah yang membuatnya ampuh membunuh mikroorganisme.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Klorin sebagai Disinfektan Air$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Sejak awal abad ke-20, klorin dipakai untuk mendisinfeksi air minum di seluruh dunia. Dalam dosis kecil yang terkontrol, klorin membunuh bakteri dan virus penyebab penyakit seperti kolera dan tifus, menyelamatkan jutaan nyawa.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Penggunaan Sehari-hari$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Selain air minum, klorin dipakai di kolam renang, pemutih pakaian (natrium hipoklorit), dan pembersih rumah tangga. Produk pembersih berklorin efektif membunuh kuman di lantai, kamar mandi, dan dapur.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Keamanan: Gunakan dengan Benar$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Klorin pekat berbahaya: jangan mencampur pemutih dengan pembersih toilet yang mengandung asam karena menghasilkan gas beracun. Selalu gunakan di ruangan berventilasi baik, simpan jauh dari anak-anak, dan ikuti takaran pada kemasan.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e8800005-8888-4888-8888-888888888888', 'SCH-SMP-SEJ8-001', 'd4444444-4444-4444-4444-444444444444', $$IPS Kelas 9: Proklamasi Kemerdekaan Indonesia$$, 'ips-kelas-9-proklamasi-kemerdekaan', $$Materi IPS kelas 9 tentang Proklamasi Kemerdekaan Indonesia: latar belakang, peristiwa, dan maknanya.$$, 'id', 8, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, siswa diharapkan mampu menjelaskan latar belakang Proklamasi Kemerdekaan Indonesia, mendeskripsikan peristiwa 17 Agustus 1945, serta menganalisis makna proklamasi bagi bangsa Indonesia.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Latar Belakang Proklamasi$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Pada Agustus 1945, Jepang menyerah kepada Sekutu setelah bom atom dijatuhkan di Hiroshima dan Nagasaki. Kekosongan kekuasaan ini dimanfaatkan para tokoh Indonesia. Golongan muda mendesak Soekarno-Hatta segera memproklamasikan kemerdekaan tanpa menunggu janji Jepang.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Peristiwa Rengasdengklok$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Karena perbedaan pendapat, golongan muda membawa Soekarno dan Hatta ke Rengasdengklok pada 16 Agustus 1945 untuk mendesak proklamasi. Setelah tercapai kesepakatan, mereka kembali ke Jakarta dan naskah proklamasi dirumuskan di rumah Laksamana Maeda.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Detik-detik 17 Agustus 1945$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Naskah proklamasi diketik oleh Sayuti Melik. Pada 17 Agustus 1945 pukul 10.00 WIB, di Jalan Pegangsaan Timur Nomor 56 Jakarta, Soekarno membacakan teks proklamasi didampingi Hatta. Bendera Merah Putih dikibarkan dan lagu Indonesia Raya dinyanyikan.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Makna Proklamasi bagi Bangsa Indonesia$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Proklamasi menandai lahirnya negara Indonesia yang merdeka dan berdaulat. Ia menjadi puncak perjuangan melawan penjajah sekaligus titik awal membangun negara. Setiap tahun diperingati sebagai Hari Kemerdekaan pada 17 Agustus.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal dan Kunci Jawaban$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$Jelaskan latar belakang peristiwa Rengasdengklok! Jawab: golongan muda mendesak Soekarno-Hatta segera memproklamasikan kemerdekaan karena Jepang telah menyerah dan terjadi kekosongan kekuasaan.$$,$$Sebutkan isi singkat teks Proklamasi! Jawab: bangsa Indonesia menyatakan kemerdekaannya; pemindahan kekuasaan diselenggarakan dengan saksama dalam tempo sesingkat-singkatnya.$$,$$Mengapa proklamasi disebut puncak perjuangan bangsa? Jawab: proklamasi adalah hasil akumulasi perjuangan panjang melawan penjajah yang akhirnya membuahkan negara merdeka dan berdaulat.$$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e8800006-8888-4888-8888-888888888888', 'SCH-SD-MAT23-001', 'd3000002-0000-0000-0000-000000000002', $$Matematika Kelas 1: Pengurangan$$, 'matematika-kelas-1-pengurangan', $$Belajar pengurangan untuk kelas 1 SD: konsep mengambil, pengurangan bersusun sederhana, dan latihan soal.$$, 'id', 6, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah belajar, kamu bisa melakukan pengurangan bilangan sampai 20 dengan benar, memahami pengurangan sebagai kebalikan penjumlahan, dan menyelesaikan soal cerita sederhana.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Pengurangan$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Pengurangan artinya mengambil sebagian. Contoh: kamu punya 7 permen, dimakan 2, sisanya 5. Ditulis 7 - 2 = 5. Tanda kurang (-) dibaca kurang, dan hasilnya disebut selisih.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Pengurangan dengan Gambar$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Gambar 9 apel, lalu coret 4 apel. Hitung yang tidak dicoret: ada 5. Jadi 9 - 4 = 5. Cara menggambar seperti ini membantu memahami sebelum menghafal.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Pengurangan Bersusun ke Bawah$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Tulis angka yang besar di atas, angka kecil di bawah, luruskan satuannya. Contoh: 15 - 7. Kurangi satuan dulu: 5 tidak bisa dikurangi 7, pinjam 1 puluhan sehingga jadi 15 - 7 = 8. Hasilnya 8.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Hubungan dengan Penjumlahan$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Pengurangan adalah kebalikan penjumlahan. Jika 8 + 3 = 11, maka 11 - 3 = 8. Kamu bisa memeriksa jawaban pengurangan dengan menjumlahkan hasilnya dan pengurangnya.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Ayo Berlatih dan Kunci Jawaban$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$12 - 5 = 7$$,$$18 - 9 = 9$$,$$Ibu membeli 14 telur, 6 telur pecah. Sisa telur Ibu: 14 - 6 = 8 butir.$$,$$20 - 13 = 7$$])));
